486	        exec_permission_approvals_enabled: bool,
487	    ) -> DeveloperInstructions {
488	        let on_request_instructions = || {
489	            let on_request_rule = if exec_permission_approvals_enabled {
490	                APPROVAL_POLICY_ON_REQUEST_RULE_REQUEST_PERMISSION
491	            } else {
492	                APPROVAL_POLICY_ON_REQUEST_RULE
493	            };
494	            let command_prefixes = format_allow_prefixes(exec_policy.get_allowed_prefixes());
495	            match command_prefixes {
496	                Some(prefixes) => {
497	                    format!(
498	                        "{on_request_rule}\n## Approved command prefixes\nThe following prefix rules have already been approved: {prefixes}"
499	                    )
500	                }
501	                None => on_request_rule.to_string(),
502	            }
503	        };
504	        let text = match approval_policy {
505	            AskForApproval::Never => APPROVAL_POLICY_NEVER.to_string(),
506	            AskForApproval::UnlessTrusted => APPROVAL_POLICY_UNLESS_TRUSTED.to_string(),
507	            AskForApproval::OnFailure => APPROVAL_POLICY_ON_FAILURE.to_string(),
508	            AskForApproval::OnRequest => on_request_instructions(),
509	            AskForApproval::Granular(granular_config) => {
510	                let on_request_instructions = on_request_instructions();
511	                let sandbox_approval = granular_config.sandbox_approval;
512	                let rules = granular_config.rules;
513	                let skill_approval = granular_config.skill_approval;
514	                let request_permissions = granular_config.request_permissions;
515	                let mcp_elicitations = granular_config.mcp_elicitations;
516	                format!(
517	                    "{on_request_instructions}\n\n\
518	                     Approval policy is `granular`.\n\
519	                     - `sandbox_approval`: {sandbox_approval}\n\
520	                     - `rules`: {rules}\n\
521	                     - `skill_approval`: {skill_approval}\n\
522	                     - `request_permissions`: {request_permissions}\n\
523	                     - `mcp_elicitations`: {mcp_elicitations}\n\
524	                     When a category is `true`, requests in that category are allowed. When it is `false`, they are auto-rejected instead of prompting the user."
525	                )
526	            }
527	        };
528	
529	        DeveloperInstructions::new(text)
530	    }
